    tiling.set_n(n);
    tiling.set_c(c);
    tiling.set_h(h);
    tiling.set_w(w);
    tiling.set_tileNum(TILE_NUM);
    // 简单切分 H*W 维度
    uint32_t tileHW = (hw / TILE_NUM == 0) ? hw : (hw / TILE_NUM);
    if (tileHW == 0) tileHW = hw;
    tiling.set_tileHW(tileHW);

